import React, { useEffect, useState } from 'react';

type Product = {
  name: string;
  price: number;
  description: string;
  img: string;
};

const Home: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch('http://localhost:4000/products')
      .then(res => res.json())
      .then(data => {
        setProducts(data);
        setLoading(false);
      })
      .catch(() => {
        setError('Failed to load products');
        setLoading(false);
      });
  }, []);

  return (
    <div style={{ maxWidth: 1200, margin: '0 auto', padding: '32px 16px' }}>
      <h1 style={{ textAlign: 'center', marginBottom: 32 }}>
        <span>Supercharge Your </span>
        <span style={{ background: '#fff200', color: '#222', padding: '0 4px', borderRadius: 4 }}>Health</span>
      </h1>
      {loading ? (
        <div style={{ textAlign: 'center', marginTop: 32 }}>Loading products...</div>
      ) : error ? (
        <div style={{ textAlign: 'center', color: 'red', marginTop: 32 }}>{error}</div>
      ) : (
        <div style={{ display: 'flex', gap: 32, flexWrap: 'wrap', justifyContent: 'center' }}>
          {products.map((p, idx) => (
            <div key={idx} style={{ background: '#fff', borderRadius: 16, boxShadow: '0 2px 8px #eee', width: 260, padding: 24, display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
              <img src={p.img} alt={p.name} style={{ width: 180, height: 120, objectFit: 'contain', marginBottom: 16 }} />
              <h3 style={{ fontWeight: 700, marginBottom: 8 }}>{p.name}</h3>
              <p style={{ fontSize: 14, color: '#222', marginBottom: 16 }}>{p.description}</p>
              <div style={{ fontWeight: 700, marginBottom: 8 }}>USD ${p.price.toFixed(2)} <span style={{ fontWeight: 400, fontSize: 12 }}>Retail</span></div>
              <label style={{ marginBottom: 8, fontSize: 14 }}>
                <input type="checkbox" style={{ marginRight: 8 }} /> Subscribe & save 25%
              </label>
              <button style={{ width: '100%', padding: '8px 0', borderRadius: 8, border: '1px solid #222', background: '#fff', fontWeight: 600, fontSize: 16, cursor: 'pointer' }}>Add to Cart +</button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Home;
